const languageSelect = document.getElementById('language-select');
const themeSelect = document.getElementById('theme-select');
const themeMedia = matchMedia('(prefers-color-scheme: dark)');

function readSetting(key, fallback) {
  try { return localStorage.getItem(key) || fallback; } catch (error) { return fallback; }
}
function saveSetting(key, value) {
  try { localStorage.setItem(key, value); } catch (error) {}
}
function applyLanguage(language) {
  const lang = translations[language] ? language : 'pt';
  const copy = translations[lang];
  document.documentElement.lang = lang === 'pt' ? 'pt-BR' : lang;
  languageSelect.value = lang;
  document.getElementById('language-current').textContent = lang.toUpperCase();
  document.querySelectorAll('[data-i18n]').forEach((element) => {
    const value = copy[element.dataset.i18n];
    if (value !== undefined) element.textContent = value;
  });
  document.querySelectorAll('[data-i18n-aria]').forEach((element) => {
    const value = copy[element.dataset.i18nAria];
    if (value !== undefined) element.setAttribute('aria-label', value);
  });
  document.querySelectorAll('[data-i18n-alt]').forEach((element) => {
    const value = copy[element.dataset.i18nAlt];
    if (value !== undefined) element.setAttribute('alt', value);
  });
  const optionLabels = { system: copy.themeSystem, light: copy.themeLight, dark: copy.themeDark };
  themeSelect.querySelectorAll('option').forEach((option) => { option.textContent = optionLabels[option.value]; });
  document.title = copy.metaTitle;
  document.querySelector('meta[name="description"]').setAttribute('content', copy.metaDesc);
  document.querySelector('meta[property="og:title"]').setAttribute('content', copy.metaTitle);
  document.querySelector('meta[property="og:description"]').setAttribute('content', copy.metaDesc);
  saveSetting('ir-lang', lang);
}
function applyTheme(setting) {
  const choice = ['system', 'light', 'dark'].includes(setting) ? setting : 'system';
  const actual = choice === 'system' ? (themeMedia.matches ? 'dark' : 'light') : choice;
  document.documentElement.dataset.theme = actual;
  themeSelect.value = choice;
  document.getElementById('theme-icon-use').setAttribute('href', '#theme-' + choice);
  document.querySelector('meta[name="theme-color"]').setAttribute('content', actual === 'dark' ? '#0c1115' : '#f5f1e9');
  saveSetting('ir-theme', choice);
}

const params = new URLSearchParams(location.search);
applyLanguage(params.get('lang') || readSetting('ir-lang', 'pt'));
applyTheme(readSetting('ir-theme', 'system'));
languageSelect.addEventListener('change', () => applyLanguage(languageSelect.value));
themeSelect.addEventListener('change', () => applyTheme(themeSelect.value));
themeMedia.addEventListener('change', () => {
  if (themeSelect.value === 'system') applyTheme('system');
});
document.getElementById('year').textContent = new Date().getFullYear();

const navLinks = Array.from(document.querySelectorAll('.nav a[data-section]'));
const trackedSections = navLinks.map((link) => document.getElementById(link.dataset.section));
const progress = document.getElementById('reading-progress');
let scrollScheduled = false;
function updateScrollState() {
  scrollScheduled = false;
  const referenceLine = Math.min(innerHeight * .38, 330);
  let active = null;
  trackedSections.forEach((section) => {
    const rect = section.getBoundingClientRect();
    if (rect.top <= referenceLine && rect.bottom > referenceLine) active = section.id;
  });
  navLinks.forEach((link) => {
    const selected = link.dataset.section === active;
    link.classList.toggle('active', selected);
    if (selected) link.setAttribute('aria-current', 'location');
    else link.removeAttribute('aria-current');
  });
  const available = document.documentElement.scrollHeight - innerHeight;
  progress.style.width = (available > 0 ? Math.min(100, Math.max(0, scrollY / available * 100)) : 0) + '%';
}
function scheduleScrollUpdate() {
  if (scrollScheduled) return;
  scrollScheduled = true;
  requestAnimationFrame(updateScrollState);
}
addEventListener('scroll', scheduleScrollUpdate, { passive: true });
addEventListener('resize', scheduleScrollUpdate);
addEventListener('hashchange', scheduleScrollUpdate);
updateScrollState();

if ('IntersectionObserver' in window && !matchMedia('(prefers-reduced-motion: reduce)').matches) {
  document.body.classList.add('js-ready');
  const revealObserver = new IntersectionObserver((entries, observer) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        entry.target.classList.add('is-visible');
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: .08, rootMargin: '0px 0px -35px 0px' });
  document.querySelectorAll('[data-reveal]').forEach((element) => revealObserver.observe(element));
}
